export function portalState(t,f={}){const start=f.depotPortalStart??50.5,grow=Math.max(.1,f.depotPortalGrow??1.15),hold=Math.max(0,f.depotPortalHold??.35),close=Math.max(.1,f.depotPortalClose??1.25),peak=start+grow,clear=peak+hold+close,growth=depotEase((t-start)/grow),release=depotEase((t-peak-hold)/close),vanishAt=f.depotVanishStart??51.1,vanish=depotEase((t-vanishAt)/Math.max(.1,f.depotVanishTime??1.05));return {start,peak,clear,growth,release,energy:growth*(1-release),vanish,opacity:1-depotEase((vanish-.6)/.4),scale:1-vanish*.92,yaw:vanish*(f.depotPortalYaw??34),shatter:depotEase((t-(f.depotShatterStart??44))/Math.max(.1,f.depotShatterTime??3)),dark:depotEase((t-(f.depotLateDarkStart??45))/Math.max(.1,f.depotLateDarkTime??5)),titleEarliest:Math.max(clear,vanishAt+(f.depotVanishTime??1.05))+(f.depotPortalTitleGap??.3)}}
